import os
import shutil

BACKUP_DIR = '/tmp/backup'


def task_func(directory):
    """Restore a directory from its backup, returning its path or an error."""
    if not os.path.exists(BACKUP_DIR):
        return f'Backup directory {BACKUP_DIR} does not exist. Cannot rollback update.'

    try:
        if os.path.exists(directory):
            shutil.rmtree(directory)
        shutil.copytree(BACKUP_DIR, directory)
        return directory
    except Exception as exc:
        return f'Error during rollback: {exc}'

import warnings
import os
import glob
import shutil
import time


def task_func(SOURCE_DIR, DEST_DIR, EXTENSIONS):
    """Move files with the requested extensions, warning on failed transfers."""
    transferred_files = []
    for extension in EXTENSIONS:
        pattern = os.path.join(glob.escape(SOURCE_DIR), '*' + extension)
        for source in glob.glob(pattern):
            if not os.path.isfile(source):
                continue
            name = os.path.basename(source)
            try:
                os.makedirs(DEST_DIR, exist_ok=True)
                shutil.move(source, DEST_DIR)
            except Exception as error:
                warnings.warn(f'Could not transfer {name}: {error}', stacklevel=2)
            else:
                transferred_files.append(name)
    return transferred_files

