import pathlib
import os


def task_func(path: str, delimiter: str = os.path.sep) -> list:
    """Validate a path and split it into components using the given delimiter."""
    if not path:
        return []

    if any(character in path for character in '<>:"|?*'):
        raise ValueError('Path contains invalid characters.')

    normalized_path = pathlib.Path(path.replace('\\', '/'))
    if delimiter and all(character == '\\' for character in delimiter):
        delimiter = '/'
    else:
        delimiter = delimiter.replace('\\', '/')
    return str(normalized_path).split(delimiter)

